function saida(nome) { try { const j = $(nome).first().json; return j && j.output !== undefined ? j.output : null; } catch (e) { return null; } }
const base = $('Agente de Ingestão (Normalizar)').first().json;
const achadosOut = saida('Agente Heurístico UX') || {};
const diagOut = saida('Agente Diagnóstico de Funil') || {};
const iceOut = saida('Agente Priorização ICE') || {};
const sinteseOut = saida('Agente de Síntese');
const autoOut = saida('Agente Autocrítica (Revisor)') || {};

const achados = achadosOut.achados || [];
const gargalos = diagOut.gargalos || [];
const hipoteses = iceOut.hipoteses || [];
const sintese_md = typeof sinteseOut === 'string' ? sinteseOut : (sinteseOut ? JSON.stringify(sinteseOut) : '');
const autocritica = { score: Number(autoOut.score) || 0, recomendacao: autoOut.recomendacao || 'revisar', problemas: autoOut.problemas || [], pontos_fortes: autoOut.pontos_fortes || [] };

const pipelineOk = achados.length > 0 || gargalos.length > 0 || hipoteses.length > 0;
let status = 'erro_pipeline';
if (pipelineOk) status = autocritica.score >= 7 ? 'aguardando_gate' : 'requer_revisao';

const soma = (arr, sel) => arr.reduce((acc, g) => acc + (Number(sel(g)) || 0), 0);
const oportunidade_total_min = Math.round(soma(gargalos, g => (g.oportunidade_reais_mes || {}).min));
const oportunidade_total_max = Math.round(soma(gargalos, g => (g.oportunidade_reais_mes || {}).max));

const dados = {
  ciclo_id: base.ciclo_id, cliente: base.cliente, periodo: base.periodo, registro: base.registro,
  kpis: base.kpis, taxas_funil: base.taxas_funil, funil_eventos: base.funil_eventos, canais: base.canais, devices: base.devices,
  clarity_metricas: base.clarity_metricas, backlog_jira: base.backlog_jira, anomalias: base.anomalias, coleta: base.coleta,
  achados, gargalos, hipoteses, autocritica, sintese_md,
  resumo_diagnostico: diagOut.resumo_diagnostico || '',
  oportunidade_total_min, oportunidade_total_max
};

return [{ json: {
  ciclo_id: base.ciclo_id, cliente: base.cliente, status,
  score_autocritica: autocritica.score,
  problemas_revisor: autocritica.problemas,
  oportunidade_total_min, oportunidade_total_max,
  hipoteses_qtd: hipoteses.length,
  sintese_md,
  dados_json: JSON.stringify(dados),
  criado_em: new Date().toISOString()
} }];

const p = $input.first().json;
const base = $('Agente de Ingestão (Normalizar)').first().json;
const brl = v => 'R$ ' + Math.round(v || 0).toLocaleString('pt-BR');
const gateUrl = 'https://n8n-prod.cadastra.com/webhook/cro-next-gate';
const cor = p.status === 'aguardando_gate' ? '#10b981' : (p.status === 'requer_revisao' ? '#f59e0b' : '#ef4444');
const rotulo = p.status === 'aguardando_gate' ? 'AGUARDANDO SEU GATE' : (p.status === 'requer_revisao' ? 'REQUER REVISÃO (autocrítica < 7)' : 'ERRO NO PIPELINE');
const problemas = p.problemas_revisor || [];
const email_html =
  '<div style="font-family:Arial,sans-serif;max-width:660px">' +
  '<h2>🏭 CRO Next — Ciclo pronto: ' + p.cliente + '</h2>' +
  '<p><span style="background:' + cor + ';color:#fff;padding:3px 10px;border-radius:12px;font-size:12px;font-weight:bold">' + rotulo + '</span></p>' +
  '<table style="border-collapse:collapse;font-size:13px">' +
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Ciclo</td><td><b>' + p.ciclo_id + '</b></td></tr>' +
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Período</td><td>' + base.periodo + '</td></tr>' +
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Autocrítica</td><td><b>' + Number(p.score_autocritica).toFixed(1) + '/10</b></td></tr>' +
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Oportunidade mapeada</td><td><b>' + brl(p.oportunidade_total_min) + ' – ' + brl(p.oportunidade_total_max) + '/mês</b></td></tr>' +
  '<tr><td style="padding:4px 12px 4px 0;color:#6b7280">Hipóteses qualificadas</td><td>' + p.hipoteses_qtd + '</td></tr>' +
  '</table>' +
  (problemas.length ? '<p style="font-size:13px"><b>Problemas apontados pelo revisor:</b></p><ul style="font-size:13px">' + problemas.map(x => '<li>' + x + '</li>').join('') + '</ul>' : '') +
  '<p style="margin-top:16px"><' + 'a hr' + 'ef="' + gateUrl + '" style="background:#FF5C28;color:#fff;padding:12px 22px;border-radius:10px;text-decoration:none;font-weight:bold">Abrir Gate Humano →</a></p>' +
  '<p style="color:#6b7280;font-size:12px">Você aprova, edita e decide a aposta. Nada chega ao cliente sem o seu gate.</p></div>';

return [{ json: {
  ...p,
  email_destino: (base.registro || {}).email_analista || 'tsoares@cadastra.com',
  email_assunto: (p.status === 'aguardando_gate' ? '🏭 CRO Next | ' : '⚠️ CRO Next | ') + p.cliente + ' — ciclo ' + p.ciclo_id + ' (' + rotulo.toLowerCase() + ')',
  email_html
} }];
